		trackedEvents: trackedEvents(runs),
		scrollAbsence: runs[0]!.scrollAbsence,
		buildLanes: {
			baseline: {
				angular: 'Angular 13.2',
				builder: '@angular-builders/custom-webpack:browser over ./webpack.config.js',
